fn frame(t: i32) {
    let pal = [0xff4040, 0xffc040, 0x40ff70, 0x40c0ff, 0x8060ff, 0xff60c0];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 30);
        host::display::state_set(2, 40);
        host::display::state_set(3, 2);
        host::display::state_set(4, 2);
    }
    let mut x: i32 = host::display::state_get(1);
    let mut y: i32 = host::display::state_get(2);
    let mut vx: i32 = host::display::state_get(3);
    let mut vy: i32 = host::display::state_get(4);
    let mut hits: i32 = host::display::state_get(5);
    x = x + vx;
    y = y + vy;
    if x < 0 { x = 0; vx = 0 - vx; hits = hits + 1; }
    if x > w - 48 { x = w - 48; vx = 0 - vx; hits = hits + 1; }
    if y < 0 { y = 0; vy = 0 - vy; hits = hits + 1; }
    if y > h - 22 { y = h - 22; vy = 0 - vy; hits = hits + 1; }
    host::display::state_set(1, x);
    host::display::state_set(2, y);
    host::display::state_set(3, vx);
    host::display::state_set(4, vy);
    host::display::state_set(5, hits);
    host::display::clear(0x000000);
    host::display::fill_rect(x, y, 48, 22, pal[hits % 6]);
    host::display::draw_string(x + 8, y + 4, "DVD", 0x000000, 2);
    host::display::draw_number(6, 6, hits, 0x606060, 1);
    host::display::present();
}
